-- FRM-011 is renamed "Customer, Recall and Crisis Contact List" (New -> v2), and the programs
-- that cite it by title are corrected.
--
-- Owner's decision, 2026-10-10. The contact list is where the site's customers are kept, and from
-- today the customer fields of seven records offer the names on it (migration 20261010000009). The
-- old title did not say so. The document number does not change, so every link keeps working.
--
--   FRM-011   title, the note at the top (how to add a customer), the sign-off statement; New -> v2
--   FSQM-011  v2  -> v3   the Linked forms line for FRM-011
--   FSQM-023  New -> v2   the same
--   FSQM-024  New -> v2   the same
--   FSQM-025  (draft)     the same line, no revision - it has not been issued
--
-- Approved by GJM, effective 2026-10-10. No table, column, procedure or limit changes anywhere.
--
-- Safe to run twice: a document that already reads as intended is left alone, so no second history
-- snapshot is taken. A document in any other shape stops the whole migration.

do $$
declare
  schema_old constant jsonb := $s1${"sections": [{"id": "list", "title": "1. The contact list", "fields": [{"id": "how_this_works", "text": "This is the list used in a recall (FSQM-023) and in a crisis (FSQM-024). Keep one current list: when a contact changes, and at every mock recall and crisis test, copy the last entry, correct it and submit it. Add a line for every customer. Suppliers' contacts are on their FRM-202 approval records.", "type": "info", "label": "How to use this"}, {"id": "reviewed_on", "type": "date", "label": "Checked on", "width": "third", "required": true, "showInList": true}, {"id": "off_site_copy", "help": "A copy that can be reached when the site and the Team Portal cannot", "type": "text", "label": "Where the off-site copy is kept", "width": "half"}, {"id": "contacts", "rows": {"mode": "fixed", "labels": ["Senior Site Management", "SQF Practitioner", "Substitute SQF Practitioner", "SQFI", "Certification body", "FDA - recall coordinator / Reportable Food Registry", "FDACS Division of Food Safety", "Legal counsel", "Food safety consultant", "Insurer", "Landlord", "City of Sanford Utilities (water)", "Electricity supplier"], "addLabel": "Add contact", "deletable": true, "labelHeader": "Contact", "defaultValues": [{"when": "Recall coordinator and crisis lead - first call for any event", "group": "Crisis team"}, {"when": "Trace, holds and investigation", "group": "Crisis team"}, {"when": "When the SQF Practitioner is away", "group": "Crisis team"}, {"when": "In writing within 24 hours of a recall or a food safety event needing public notification", "email": "foodsafetycrisis@sqfi.com", "group": "SQF"}, {"when": "In writing within 24 hours, as for SQFI - to be added when contracted", "group": "SQF"}, {"when": "Recall; Reportable Food Registry report within 24 hours where serious harm is probable", "group": "Authority"}, {"when": "Recall or a crisis affecting the food permit", "group": "Authority"}, {"when": "Recall, or any public statement", "group": "Advice"}, {"when": "Assessing risk and held product", "group": "Advice"}, {"when": "Recall or damage to the site", "group": "Advice"}, {"when": "Building damage, access, the complex's backflow device", "group": "Utility / landlord"}, {"when": "Boil-water notice, loss of water", "group": "Utility / landlord"}, {"when": "Loss of power", "group": "Utility / landlord"}]}, "type": "grid", "label": "Contacts", "columns": [{"id": "group", "type": "select", "label": "Group", "width": 1.2, "options": ["Crisis team", "Customer (brand owner)", "Supplier", "Authority", "SQF", "Advice", "Utility / landlord"]}, {"id": "name", "type": "text", "label": "Person", "width": 1.3, "scanFact": "none"}, {"id": "phone", "type": "text", "label": "Phone", "width": 1.1, "scanFact": "none"}, {"id": "email", "type": "text", "label": "Email", "width": 1.5, "scanFact": "none"}, {"id": "when", "type": "text", "label": "When to contact", "width": 2, "scanFact": "none"}], "required": true, "rowDialog": true}]}, {"id": "sign", "title": "2. Sign-off", "fields": [{"id": "checked_by", "role": "filler", "type": "signature", "label": "Checked by", "required": true, "statement": "Every number and address on this list was checked and is current."}, {"id": "approved_by", "role": "verifier", "type": "signature", "label": "Senior Site Management", "required": true, "statement": "This is the site's current recall and crisis contact list."}]}], "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": false, "requireVerification": true, "instanceTitleTemplate": "Contact list - {reviewed_on}"}, "schemaVersion": 1}$s1$::jsonb;
  schema_new constant jsonb := $s2${"sections": [{"id": "list", "title": "1. The contact list", "fields": [{"id": "how_this_works", "text": "This is the list used in a recall (FSQM-023) and in a crisis (FSQM-024). Keep one current list: when a contact changes, and at every mock recall and crisis test, copy the last entry, correct it and submit it. Add a line for every customer, with the group Customer (brand owner) and the customer's name under Contact: this list is where the site's customers are kept, and the Customer field of the dispatch, release, retention sample, label review, product specification, complaint and recall records offers the names on it. Suppliers' contacts are on their FRM-202 approval records.", "type": "info", "label": "How to use this"}, {"id": "reviewed_on", "type": "date", "label": "Checked on", "width": "third", "required": true, "showInList": true}, {"id": "off_site_copy", "help": "A copy that can be reached when the site and the Team Portal cannot", "type": "text", "label": "Where the off-site copy is kept", "width": "half"}, {"id": "contacts", "rows": {"mode": "fixed", "labels": ["Senior Site Management", "SQF Practitioner", "Substitute SQF Practitioner", "SQFI", "Certification body", "FDA - recall coordinator / Reportable Food Registry", "FDACS Division of Food Safety", "Legal counsel", "Food safety consultant", "Insurer", "Landlord", "City of Sanford Utilities (water)", "Electricity supplier"], "addLabel": "Add contact", "deletable": true, "labelHeader": "Contact", "defaultValues": [{"when": "Recall coordinator and crisis lead - first call for any event", "group": "Crisis team"}, {"when": "Trace, holds and investigation", "group": "Crisis team"}, {"when": "When the SQF Practitioner is away", "group": "Crisis team"}, {"when": "In writing within 24 hours of a recall or a food safety event needing public notification", "email": "foodsafetycrisis@sqfi.com", "group": "SQF"}, {"when": "In writing within 24 hours, as for SQFI - to be added when contracted", "group": "SQF"}, {"when": "Recall; Reportable Food Registry report within 24 hours where serious harm is probable", "group": "Authority"}, {"when": "Recall or a crisis affecting the food permit", "group": "Authority"}, {"when": "Recall, or any public statement", "group": "Advice"}, {"when": "Assessing risk and held product", "group": "Advice"}, {"when": "Recall or damage to the site", "group": "Advice"}, {"when": "Building damage, access, the complex's backflow device", "group": "Utility / landlord"}, {"when": "Boil-water notice, loss of water", "group": "Utility / landlord"}, {"when": "Loss of power", "group": "Utility / landlord"}]}, "type": "grid", "label": "Contacts", "columns": [{"id": "group", "type": "select", "label": "Group", "width": 1.2, "options": ["Crisis team", "Customer (brand owner)", "Supplier", "Authority", "SQF", "Advice", "Utility / landlord"]}, {"id": "name", "type": "text", "label": "Person", "width": 1.3, "scanFact": "none"}, {"id": "phone", "type": "text", "label": "Phone", "width": 1.1, "scanFact": "none"}, {"id": "email", "type": "text", "label": "Email", "width": 1.5, "scanFact": "none"}, {"id": "when", "type": "text", "label": "When to contact", "width": 2, "scanFact": "none"}], "required": true, "rowDialog": true}]}, {"id": "sign", "title": "2. Sign-off", "fields": [{"id": "checked_by", "role": "filler", "type": "signature", "label": "Checked by", "required": true, "statement": "Every number and address on this list was checked and is current."}, {"id": "approved_by", "role": "verifier", "type": "signature", "label": "Senior Site Management", "required": true, "statement": "This is the site's current customer, recall and crisis contact list."}]}], "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": false, "requireVerification": true, "instanceTitleTemplate": "Contact list - {reviewed_on}"}, "schemaVersion": 1}$s2$::jsonb;
  note_011 constant jsonb := $s3$"v2 - 2026-10-10 - Renamed \"Customer, Recall and Crisis Contact List\".\n\nThe list was already where each customer is kept with a way to reach them, and the recall trace matches the customer on a dispatch record against it. From this revision the customer fields of FRM-002, FRM-012, FRM-601, FRM-701, FRM-703, FRM-704 and FRM-801 offer the customers on the current list, so the title now says what the list is used for (owner's decision, 2026-10-10). The note at the top says how to add a customer. The table, its columns and the sign-off are unchanged."$s3$::jsonb;
  plan constant jsonb := $s4$[{"num": "FSQM-011", "rev": "v2", "next": "v3", "refs_old": "FRM-009 - Monthly SQF Update Record\nFRM-001 - Management Review Record\nFRM-007 - Corrective & Preventive Action (CAPA) Report\nFRM-011 - Recall and Crisis Contact List", "refs_new": "FRM-009 - Monthly SQF Update Record\nFRM-001 - Management Review Record\nFRM-007 - Corrective & Preventive Action (CAPA) Report\nFRM-011 - Customer, Recall and Crisis Contact List", "hist_old": "New - 2026-10-05 - DRAFT under D-12, for the Minor findings against 2.4.1.2, 2.4.1.3 and 2.6.3.4. The site had no regular source of news about food law and no written 24-hour notice for a regulatory warning.\n\nNO NEW FORM. The monthly update (FRM-009) already has a row for changes affecting the SQF System, and that is where the month's news is reported, including a month with none. A regulatory warning is rare and already needs a corrective action, so the notice is attached to that FRM-007. The 24-hour notice in a recall (2.6.3.4) is already written in FSQM-023 and is only pointed to here.\n\nALCOHOL: the site holds no federal or state alcohol permit. The rum is supplied by the customer. Whether a permit is needed to hold it and bake with it is being confirmed; if one is, this program is revised and the alcohol regulator is added as a source.\n\nISSUED 2026-10-05. FRM-009 goes to v2 in the same change: its row \"Changes affecting the SQF System\" now names changes in food law, guidance and codes of practice, since that row is where the month's news is reported. What the draft listed to confirm: (1) SOURCES. The FDA and SQFI subscriptions were set up on 2026-10-05, and the FDACS food permit carries a current email address, which is where FDACS sends its notices. The subscriptions go to one address for now and a dedicated address is being set up; the procedure therefore names an address chosen by Senior Site Management, not a position's own mailbox. (2) ALCOHOL - see above. (3) RENEWALS. The FDACS permit and the local licence are each renewed before the date printed on them; the procedure says that and no longer says \"every year\". (4) CERTIFICATION BODY. None is contracted yet. Its own rule on what it must be told is added when one is.\n\nv2 - 2026-10-06 - ALCOHOL CONFIRMED. The point left open at issue is answered: no Florida alcoholic beverage licence or permit is needed to store rum or to bake with it, because it is used only as a food ingredient. The basis is the Florida Division of Alcoholic Beverages and Tobacco's Declaratory Statement DBPR 2013-114 (2014), in which the Division declines to regulate alcohol used as a flavoring additive or ingredient in commercial food production. The rum cake is registered with the federal Alcohol and Tobacco Tax and Trade Bureau as a food product. One paragraph is added under Registrations and permits to say so; nothing else in the procedure changes, and no alcohol regulator is added as a source. A copy of the declaratory statement is kept with this program.", "hist_new": "v3 - 2026-10-10 - FRM-011 is cited by its new title.\n\nFRM-011 was renamed \"Customer, Recall and Crisis Contact List\" (its v2). The list of linked forms is corrected to match. No part of the program changes.\n\nNew - 2026-10-05 - DRAFT under D-12, for the Minor findings against 2.4.1.2, 2.4.1.3 and 2.6.3.4. The site had no regular source of news about food law and no written 24-hour notice for a regulatory warning.\n\nNO NEW FORM. The monthly update (FRM-009) already has a row for changes affecting the SQF System, and that is where the month's news is reported, including a month with none. A regulatory warning is rare and already needs a corrective action, so the notice is attached to that FRM-007. The 24-hour notice in a recall (2.6.3.4) is already written in FSQM-023 and is only pointed to here.\n\nALCOHOL: the site holds no federal or state alcohol permit. The rum is supplied by the customer. Whether a permit is needed to hold it and bake with it is being confirmed; if one is, this program is revised and the alcohol regulator is added as a source.\n\nISSUED 2026-10-05. FRM-009 goes to v2 in the same change: its row \"Changes affecting the SQF System\" now names changes in food law, guidance and codes of practice, since that row is where the month's news is reported. What the draft listed to confirm: (1) SOURCES. The FDA and SQFI subscriptions were set up on 2026-10-05, and the FDACS food permit carries a current email address, which is where FDACS sends its notices. The subscriptions go to one address for now and a dedicated address is being set up; the procedure therefore names an address chosen by Senior Site Management, not a position's own mailbox. (2) ALCOHOL - see above. (3) RENEWALS. The FDACS permit and the local licence are each renewed before the date printed on them; the procedure says that and no longer says \"every year\". (4) CERTIFICATION BODY. None is contracted yet. Its own rule on what it must be told is added when one is.\n\nv2 - 2026-10-06 - ALCOHOL CONFIRMED. The point left open at issue is answered: no Florida alcoholic beverage licence or permit is needed to store rum or to bake with it, because it is used only as a food ingredient. The basis is the Florida Division of Alcoholic Beverages and Tobacco's Declaratory Statement DBPR 2013-114 (2014), in which the Division declines to regulate alcohol used as a flavoring additive or ingredient in commercial food production. The rum cake is registered with the federal Alcohol and Tobacco Tax and Trade Bureau as a food product. One paragraph is added under Registrations and permits to say so; nothing else in the procedure changes, and no alcohol regulator is added as a source. A copy of the declaratory statement is kept with this program."}, {"num": "FSQM-023", "rev": "New", "next": "v2", "refs_old": "FRM-012 - Withdrawal, Recall and Mock Recall Record\nFRM-011 - Recall and Crisis Contact List\nFRM-520 - Production Lot Record\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-801 - Dispatch and Vehicle Loading Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-703 - Retention Sample Log\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "refs_new": "FRM-012 - Withdrawal, Recall and Mock Recall Record\nFRM-011 - Customer, Recall and Crisis Contact List\nFRM-520 - Production Lot Record\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-801 - Dispatch and Vehicle Loading Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-703 - Retention Sample Log\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "hist_old": "New - 2026-10-01 - DRAFT under D-21, for the Minor findings against 2.6.3.1 and 2.6.3.2. The site had no withdrawal or recall procedure and had never run a mock recall.\n\nOWNER'S ANSWERS (2026-10-01): the site co-packs under customers' brands, so the brand owner leads the recall and the site supplies the trace; the mock recall target is 4 hours; no certification body has been chosen yet.\n\nTHE MOCK RECALL IS ALSO D-20's TRACE TEST: FSQM-021 says the annual trace test is part of this test, recorded on FRM-012.\n\nAT ISSUE: activate the 'traceability_test' row on the verification schedule (FSQM-017 Part 6) against FRM-012, yearly; issue FSQM-021 and FRM-520 first or with it.\n\nTO CONFIRM BEFORE ISSUE: (1) the customer agreements do make the brand owner responsible for consumer notices; (2) the certification body, once contracted, added to FRM-011; (3) legal counsel and a food safety consultant named on FRM-011; (4) the first mock recall run and recorded.\n\nRECALL WORKSPACE 2026-10-02 (owner): the trace is pulled from the records by the Team Portal - the Traceability page, and the workspace above each FRM-012 record with the 4-hour and 24-hour clocks and these steps ticked from the record. FRM-012 gained what it starts from, the hold reference, the decision, and a per-lot reconciliation table in place of the five quantity fields.\n\nISSUED 2026-10-07, with FSQM-024, FRM-011, FRM-012 and FRM-013; FSQM-021 and FRM-520 were issued the day before. What the draft listed to confirm (owner, 2026-10-07): (1) the customer agreements do make the brand owner responsible for telling consumers and the public, as written. (2) No certification body is contracted yet; it is added to FRM-011 when one is. (3) Legal counsel and a food safety consultant are entered on FRM-011 by Senior Site Management. (4) The first mock recall is due by 2026-12-31: the 'traceability and mock recall test' row of the verification schedule is now active, yearly, on FRM-012.", "hist_new": "v2 - 2026-10-10 - FRM-011 is cited by its new title.\n\nFRM-011 was renamed \"Customer, Recall and Crisis Contact List\" (its v2). The list of linked forms is corrected to match. No part of the program changes.\n\nNew - 2026-10-01 - DRAFT under D-21, for the Minor findings against 2.6.3.1 and 2.6.3.2. The site had no withdrawal or recall procedure and had never run a mock recall.\n\nOWNER'S ANSWERS (2026-10-01): the site co-packs under customers' brands, so the brand owner leads the recall and the site supplies the trace; the mock recall target is 4 hours; no certification body has been chosen yet.\n\nTHE MOCK RECALL IS ALSO D-20's TRACE TEST: FSQM-021 says the annual trace test is part of this test, recorded on FRM-012.\n\nAT ISSUE: activate the 'traceability_test' row on the verification schedule (FSQM-017 Part 6) against FRM-012, yearly; issue FSQM-021 and FRM-520 first or with it.\n\nTO CONFIRM BEFORE ISSUE: (1) the customer agreements do make the brand owner responsible for consumer notices; (2) the certification body, once contracted, added to FRM-011; (3) legal counsel and a food safety consultant named on FRM-011; (4) the first mock recall run and recorded.\n\nRECALL WORKSPACE 2026-10-02 (owner): the trace is pulled from the records by the Team Portal - the Traceability page, and the workspace above each FRM-012 record with the 4-hour and 24-hour clocks and these steps ticked from the record. FRM-012 gained what it starts from, the hold reference, the decision, and a per-lot reconciliation table in place of the five quantity fields.\n\nISSUED 2026-10-07, with FSQM-024, FRM-011, FRM-012 and FRM-013; FSQM-021 and FRM-520 were issued the day before. What the draft listed to confirm (owner, 2026-10-07): (1) the customer agreements do make the brand owner responsible for telling consumers and the public, as written. (2) No certification body is contracted yet; it is added to FRM-011 when one is. (3) Legal counsel and a food safety consultant are entered on FRM-011 by Senior Site Management. (4) The first mock recall is due by 2026-12-31: the 'traceability and mock recall test' row of the verification schedule is now active, yearly, on FRM-012."}, {"num": "FSQM-024", "rev": "New", "next": "v2", "refs_old": "FRM-013 - Crisis Management Review and Test Record\nFRM-011 - Recall and Crisis Contact List\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-701 - Finished Product Release Record\nFRM-903 - Daily Sanitation, Pre-Operation & Release Record\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "refs_new": "FRM-013 - Crisis Management Review and Test Record\nFRM-011 - Customer, Recall and Crisis Contact List\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-701 - Finished Product Release Record\nFRM-903 - Daily Sanitation, Pre-Operation & Release Record\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "hist_old": "New - 2026-10-01 - DRAFT under D-21, for the Minor findings against 2.6.4.1 and 2.6.4.2. The site had no crisis management plan.\n\nOWNER'S DECISION (2026-10-01): the plan is written around the one danger that matters here, a hurricane or severe storm. The other dangers the Code lists were considered and are covered by the general response rather than by parts of their own.\n\nAT ISSUE: add a yearly 'crisis plan review and test' row to the verification schedule (FSQM-017 Part 6) against FRM-013, due before 1 June.\n\nTO CONFIRM BEFORE ISSUE: (1) where the copy of the contact list is kept that can be reached without the site or the portal; (2) the insurer, landlord and utility contacts entered on FRM-011; (3) whether the temperature sensors keep recording through a power cut - if not, chilled and frozen stock after an outage has no record and is disposed of; (4) the first walk-through recorded on FRM-013.\n\nISSUED 2026-10-07, with FSQM-023 and the three records. What the draft listed to confirm (owner, 2026-10-07): (1) OFF-SITE COPY - there was none; the plan now says a printed copy is kept off the site by the SQF Practitioner and replaced each time the list is approved. (2) Insurer, landlord and utility contacts are entered on FRM-011 by Senior Site Management. (3) SENSORS - they run on batteries but the hub needs mains power, so a power cut leaves a gap in the record. The plan now says so: the units are treated as out of range for the whole gap and the product temperature is taken with the probe before anything is used. (4) The first review and test is due by 2027-05-31, before the storm season: a 'crisis management plan review and test' row is added to the verification schedule, yearly, on FRM-013.", "hist_new": "v2 - 2026-10-10 - FRM-011 is cited by its new title.\n\nFRM-011 was renamed \"Customer, Recall and Crisis Contact List\" (its v2). The list of linked forms is corrected to match. No part of the program changes.\n\nNew - 2026-10-01 - DRAFT under D-21, for the Minor findings against 2.6.4.1 and 2.6.4.2. The site had no crisis management plan.\n\nOWNER'S DECISION (2026-10-01): the plan is written around the one danger that matters here, a hurricane or severe storm. The other dangers the Code lists were considered and are covered by the general response rather than by parts of their own.\n\nAT ISSUE: add a yearly 'crisis plan review and test' row to the verification schedule (FSQM-017 Part 6) against FRM-013, due before 1 June.\n\nTO CONFIRM BEFORE ISSUE: (1) where the copy of the contact list is kept that can be reached without the site or the portal; (2) the insurer, landlord and utility contacts entered on FRM-011; (3) whether the temperature sensors keep recording through a power cut - if not, chilled and frozen stock after an outage has no record and is disposed of; (4) the first walk-through recorded on FRM-013.\n\nISSUED 2026-10-07, with FSQM-023 and the three records. What the draft listed to confirm (owner, 2026-10-07): (1) OFF-SITE COPY - there was none; the plan now says a printed copy is kept off the site by the SQF Practitioner and replaced each time the list is approved. (2) Insurer, landlord and utility contacts are entered on FRM-011 by Senior Site Management. (3) SENSORS - they run on batteries but the hub needs mains power, so a power cut leaves a gap in the record. The plan now says so: the units are treated as out of range for the whole gap and the product temperature is taken with the probe before anything is used. (4) The first review and test is due by 2027-05-31, before the storm season: a 'crisis management plan review and test' row is added to the verification schedule, yearly, on FRM-013."}, {"num": "FSQM-025", "rev": "New", "next": null, "refs_old": "FRM-014 - Food Defense and Food Fraud Review and Test Record\nFRM-905 - Visitor Sign-In Log\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-801 - Dispatch and Vehicle Loading Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-011 - Recall and Crisis Contact List\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "refs_new": "FRM-014 - Food Defense and Food Fraud Review and Test Record\nFRM-905 - Visitor Sign-In Log\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-801 - Dispatch and Vehicle Loading Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-011 - Customer, Recall and Crisis Contact List\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "hist_old": "New - 2026-10-02 - DRAFT under D-22, for the Minor findings against 2.7.1.1 to 2.7.1.4. The site had no food defense plan and no threat assessment.\n\nOWNER'S ANSWERS (2026-10-02): every outside door is locked when the site is empty and keys are held by named people; the entrance is NOT kept locked during working hours; reception is separated from production by two doors and an \"employees only\" sign; there are cameras and no intruder alarm; staff presence is shown by the timesheet.\n\nTHE NAME: SQF 2.7.1.2 ii asks for the name of the responsible senior manager. Controlled documents here name positions, so the plan names Senior Site Management and the person's name is written on each FRM-014 record.\n\nFSQM-036 named this assessment as the review of its lock-or-latch rule for collecting vehicles. The rule stands.\n\nTRAINING: TRN-011 already covers food defense and food fraud for all staff. It is to be read against this plan before issue.\n\nAT ISSUE: add a yearly 'food defense and food fraud review and test' row to the verification schedule (FSQM-017 Part 6) against FRM-014.\n\nTO CONFIRM BEFORE ISSUE: (1) the entrance chime working, and heard in the production room with the mixer and the oven running - the owner chose a chime (2026-10-02) over locking the entrance or an inner door, and the plan is written as if it is in place. On 2026-10-07 a chime is installed at the entrance and does not work; it is to be put right and tried before this plan is issued; (2) how many other outside doors there are; (3) what the cameras cover and how long recordings are kept; (4) that chemicals are locked away (the FSQM-032 locker); (5) the first review and test recorded on FRM-014.", "hist_new": "New - 2026-10-02 - DRAFT under D-22, for the Minor findings against 2.7.1.1 to 2.7.1.4. The site had no food defense plan and no threat assessment.\n\nOWNER'S ANSWERS (2026-10-02): every outside door is locked when the site is empty and keys are held by named people; the entrance is NOT kept locked during working hours; reception is separated from production by two doors and an \"employees only\" sign; there are cameras and no intruder alarm; staff presence is shown by the timesheet.\n\nTHE NAME: SQF 2.7.1.2 ii asks for the name of the responsible senior manager. Controlled documents here name positions, so the plan names Senior Site Management and the person's name is written on each FRM-014 record.\n\nFSQM-036 named this assessment as the review of its lock-or-latch rule for collecting vehicles. The rule stands.\n\nTRAINING: TRN-011 already covers food defense and food fraud for all staff. It is to be read against this plan before issue.\n\nAT ISSUE: add a yearly 'food defense and food fraud review and test' row to the verification schedule (FSQM-017 Part 6) against FRM-014.\n\nTO CONFIRM BEFORE ISSUE: (1) the entrance chime working, and heard in the production room with the mixer and the oven running - the owner chose a chime (2026-10-02) over locking the entrance or an inner door, and the plan is written as if it is in place. On 2026-10-07 a chime is installed at the entrance and does not work; it is to be put right and tried before this plan is issued; (2) how many other outside doors there are; (3) what the cameras cover and how long recordings are kept; (4) that chemicals are locked away (the FSQM-032 locker); (5) the first review and test recorded on FRM-014."}]$s4$::jsonb;
  t jsonb;
  d record;
  n_docs int;
begin
  -- FRM-011
  select count(*) into n_docs from public.sop_documents where sop_number = 'FRM-011';
  if n_docs <> 1 then
    raise exception 'FRM-011: expected one document, found %', n_docs;
  end if;
  select * into d from public.sop_documents where sop_number = 'FRM-011';
  if d.title = 'Customer, Recall and Crisis Contact List' and d.revision = 'v2' and d.content->'form_schema' = schema_new and d.content->'revision_history' = note_011 then
    raise notice 'FRM-011: already renamed as intended, left alone';
  elsif d.title = 'Recall and Crisis Contact List' and d.revision = 'New' and d.status = 'active' and d.content->'form_schema' = schema_old
        and coalesce(d.content->'revision_history', 'null'::jsonb) = 'null'::jsonb then
    update public.sop_documents
       set title = 'Customer, Recall and Crisis Contact List', revision = 'v2', effective_date = '2026-10-10', approved_by = 'GJM',
           content = jsonb_set(jsonb_set(content, '{form_schema}', schema_new), '{revision_history}', note_011)
     where id = d.id;
  else
    raise exception 'FRM-011 is not the document this migration was written against';
  end if;

  -- The programs that cite it
  for t in select * from jsonb_array_elements(plan) loop
    select count(*) into n_docs from public.sop_documents where sop_number = t->>'num';
    if n_docs <> 1 then
      raise exception '%: expected one document, found %', t->>'num', n_docs;
    end if;
    select * into d from public.sop_documents where sop_number = t->>'num';
    if d.content->'form_references' = t->'refs_new' and d.content->'revision_history' = t->'hist_new'
       and d.revision = coalesce(t->>'next', t->>'rev') then
      raise notice '%: already reads as intended, left alone', t->>'num';
    elsif d.content->'form_references' = t->'refs_old' and d.content->'revision_history' = t->'hist_old' and d.revision = t->>'rev' then
      if t->>'next' is null then
        update public.sop_documents set content = jsonb_set(content, '{form_references}', t->'refs_new') where id = d.id;
      else
        update public.sop_documents
           set content = jsonb_set(jsonb_set(content, '{form_references}', t->'refs_new'), '{revision_history}', t->'hist_new'),
               revision = t->>'next', effective_date = '2026-10-10', approved_by = 'GJM'
         where id = d.id;
      end if;
    else
      raise exception '% is not the document this migration was written against', t->>'num';
    end if;
  end loop;
end $$;
